#!/usr/bin/env python3
"""Record the coordinator's explicit read-through decisions, not a model grader.

The decision table below was written after inspecting all 108 original replies,
all visible inputs and the cited source excerpts. No score threshold is used.
"""
from collections import Counter
import json
from pathlib import Path
import sys

PROJECT=Path(__file__).resolve().parents[2]
sys.path.insert(0,str(PROJECT/'src'))
from metacom_pm.io import sha256_file
from metacom_pm.rl1.schema import digest
from metacom_pm.rl1.executor_pilot import admitted_rows
OUT=PROJECT/'outputs/pm_rl1/executor_pilot_20260929_v2'

# Within each prefix: OFF17, OFF29, R17, R29, L17, L29.
# A=accept, R=reject, U=uncertain. These are AI-assisted weak judgments.
DECISIONS={1: [('A', 'Optional school-contact/support suggestions follow the current bullying concern; no invented completed action.'), ('A', 'Optional documentation and safe-space suggestions; does not claim parents already did them.'), ('A', 'Asks about speaking with George without asserting it occurred.'), ('A', 'Optional school meeting and documentation; no historical utilization claim.'), ('U', 'Past work/home stress is visible, but challenges feel bigger than they are risks minimizing the actual bullying; not a clear supportive target.'), ('A', 'Asks about George and ignores low-information work/family event.')], 2: [('A', 'Creative careers are examples of possibilities, not guarantees; asks about parental openness.'), ('A', 'Acknowledges uncertainty and explores creative goals without new personal facts.'), ('A', 'Optional blended career examples; burnout phrased as a possible risk, no invented user history.'), ('A', 'Explores options without asserting the user chose one.'), ('R', 'Invents assistant parents, creative interests and a personal career decision to enact the RS self-disclosure.'), ('A', 'Suggests exploring combined interests without inventing assistant experience.')], 3: [('A', 'Offers listening or distraction and respects vague current work concern.'), ('A', 'Offers choice without assuming a cause.'), ('A', 'Asks duration of overwhelm; current rough week does not establish full onset.'), ('A', 'Asks duration without diagnosing.'), ('A', 'Asks current work trigger; does not import past breakup.'), ('A', 'Focuses on current work and leaves specifics open.')], 4: [('A', 'Current comfort from David supports lighter as reflection; asks permission for a Max memory.'), ('A', 'Offers optional small sharing; no assertion it has happened.'), ('A', 'Asks about David perspective without claiming his actual feelings.'), ('A', 'Asks about changes in routine after current explicit move-in.'), ('R', 'Claims prior enjoyment of dogs, absent from exact visible current prefix and RS; private history cannot supply missing author evidence.'), ('R', 'World of dogs and people who love them as you did presuppose dog-specific history from an RS suggestion; current visible prefix only says pet.')], 5: [('A', 'Reflects breakup and mixed relief/grief; necessary-step phrasing is an overstrong interpretation, not new event evidence.'), ('R', 'Converts three-year relationship duration into three years in limbo.'), ('R', 'Only way to stop uncertainty asserts a uniquely necessary resolution beyond user statement and historical intention.'), ('A', 'Explicitly recalls earlier commitment expectations and asks how the completed breakup relates; preserves intention-versus-action timing.'), ('A', 'Metaphorical support and open support-system question, not proof of a network.'), ('A', 'Limbo here refers to adjustment after breakup, not claim couple is still undecided; asks about support.')], 6: [('A', 'Acknowledges mixed friend responses and asks about specifics.'), ('A', 'Tentative reflection of hurt with an open chronology question.'), ('A', 'Sincerity question is distinct from current report of apologies; alternatives are leading but no new event asserted.'), ('A', 'Asks whether friends gave reasons at current confrontation; does not assert prior exclusion never had an excuse.'), ('A', 'Keeps friends distinct from professors.'), ('A', 'Asks about processing without importing academic events.')], 7: [('A', 'Seeks details of present classmate conflict.'), ('A', 'Asks whether work or personal issues contributed without asserting cause.'), ('A', 'Explores project impact without invented history.'), ('A', 'General study/personal stress is compatible with supplied past, but too nonspecific to count explicit historical uptake.'), ('A', 'Current classmate/project facts only.'), ('A', 'Open question about discussing conflict; not a claim of actual reconciliation.')], 8: [('A', 'Explores explicitly stated growth and fear; trigger wording is a question.'), ('A', 'Current reconnection and growth support question.'), ('A', 'Asks about communicating changes; does not conflate Henry and ex-girlfriend.'), ('A', 'Asks about old romantic patterns without importing friendship details.'), ('A', 'Invites user to identify patterns; examples are questions, not assertions.'), ('A', 'Current prior relationship and maturity, not unsupported Henry transfer.')], 9: [('A', 'Honesty/support suggestions address current struggle; metaphor is not a factual claim.'), ('A', 'Current pressures are explicit; inconsistent cup metaphor is a style defect, not invented history.'), ('A', 'Margaret trying to be strong for Emily is explicit in supplied past; current vulnerability is marked likely.'), ('U', 'Last few months adds a duration to current struggle not established in the exact messages; uncertain historical timeframe.'), ('U', 'Extra work without main-job pressure is a poorly supported way to lighten an already overloaded user; suitability uncertain.'), ('R', 'Suggests reduced schedule to stabilize finances despite pay cut and layoff threat, without acknowledging lost income; fails current-task fit.')], 10: [('A', 'Asks about review content rather than inventing it.'), ('A', 'Explores job preferences using optional examples.'), ('A', 'Current review and self-doubt only; no additional history uptake.'), ('A', 'Current work pressure and job-change question only.'), ('A', 'Explicitly recalls supplied earlier supportive conversation; asks whether it helps now without inventing a current benefit.'), ('A', 'Question about talking/support does not assert completed effective treatment.')], 11: [('A', 'AA/support connection is visible; asks attendance duration rather than asserting it.'), ('A', 'Safe space reflects current lack of judgment; asks whether Bob gave advice.'), ('A', 'Current Bob support; no invented prior success.'), ('A', 'Current support-group connection only.'), ('A', 'Does not follow irrelevant location self-disclosure.'), ('A', 'Asks about connection without inventing an assistant residence.')], 12: [('A', 'Explores tradeoffs and possible local contact without asserting availability.'), ('R', 'Break the cycle of waiting presumes passivity despite explicit ongoing search.'), ('R', 'Repeats prior failure: considered recruiter/counselor advice becomes actual outreach that helped. Source explicitly says not tried.'), ('A', 'Career support is optional; no completed-outreach claim.'), ('A', 'Started looking online is explicit in supplied event; asks about results without inventing success.'), ('A', 'Online search is supplied as past ongoing attempt; recently is imprecise but no contradictory end is visible.')], 13: [('A', 'Optional brief self-care and choice; no claim of treatment or guaranteed result.'), ('A', 'Current anxiety/work/Mark details and optional topic choice.'), ('A', 'Earlier therapy/boundary work is explicit; asks about applying it now, no friend-identity conflation.'), ('A', 'Earlier therapy grounding is explicit; current Mark discussion is a question.'), ('A', 'Breakdown/topic choice uses current input.'), ('R', 'Says user previously reported support helps ground them, but selected ME says only seeks support; imports an outcome absent from author-visible evidence.')], 14: [('A', 'Encouragement and imagined reader response rather than specific invented history; unfiltered-sharing language lacks privacy sensitivity and is a quality limitation.'), ('A', 'Optional post idea; broad audience reassurance is not an observed outcome. Superpower/clinical comparison are stylistic overstatements.'), ('A', 'Past therapy/boundaries are explicit; own-terms language allows choice. Calling blog safe is metaphorical but deserves caution in diagnostics.'), ('A', 'Therapy progress is supported by visible past; future audience benefit framed as possibility.'), ('R', 'Swaps source speaker/topic: past user talked with friend about FRIEND mental health, not user struggles.'), ('R', 'Implies that dated friend conversation disclosed user struggles; source supports friend struggles only.')], 15: [('A', 'Possible classmate motives explicitly maybe, not fact; offers space to discuss ideas.'), ('A', 'Worked hard is a generic empathetic inference about offered ideas, not a new historical episode; asks meeting pattern.'), ('A', 'Private conversation remains optional and when calm.'), ('R', 'Reasks whether ideas were dismissed and how user feels after both were already explicit; weak attentiveness target.'), ('A', 'Does not invent assistant workplace experience; asks user about past situations.'), ('A', 'Asks about user past instead of inventing an assistant story.')], 16: [('A', 'Current friend support and thesis feedback support question about next revisions.'), ('A', 'Asks whether next steps feel manageable.'), ('A', 'Separates practical ideas from emotional support as an open question.'), ('A', 'Asks about new ideas without claiming advisor outcome.'), ('A', 'Generic reassurance with optional next-step question.'), ('A', 'Respects positive update and asks about week.')], 17: [('U', 'Hand-holding/listening/feeding examples attach to you are providing; could be illustrative but literal actions not established.'), ('A', 'Small task is posed as a possibility, not completed care.'), ('U', 'Listening to mother concerns is asserted as actual behavior but not in exact current/past messages; could be broad caregiving reflection.'), ('A', 'Work, care and family outreach are explicit; presence reassurance is not a measured clinical outcome.'), ('A', 'Current caregiving and workload; asks about drains.'), ('U', 'Listening/daily tasks are presented as already delivered support; exact actions not established.')], 18: [('A', 'Optional workplace suggestions; fairness and integrity are supportive framing, not independent proof. Length and binary manager framing are limitations.'), ('A', 'Examples of professional wording are hypothetical; impulsivity is a caution, not asserted behavior.'), ('A', 'Asks about trusted support without assuming it exists.'), ('A', 'Frames perceived injustice and asks about discussions.'), ('A', 'Sister Annie support is in source-checked visible MP; optional outreach does not assert workplace expertise.'), ('A', 'Visible Annie profile supports optional outside-work conversation; no forced claim that sister can solve workplace issue.')]}

def main():
    contract=json.loads((OUT/'condition_contract_private.json').read_text())
    author=Path(json.loads((OUT/'author_pointer.json').read_text())['run_dir'])
    jobs=json.loads((author/'jobs.json').read_text());conditions={(c['index'],c['condition']):c for c in contract['conditions']}
    evidence=json.loads((OUT/'legal_evidence_private.json').read_text())
    requests={};raws={};reviews=[]
    historical={(5,'R',29),(9,'R',17),(10,'L',17),(12,'L',17),(12,'L',29),(13,'R',17),(13,'R',29),(14,'R',17),(14,'R',29),(18,'L',17),(18,'L',29)}
    for j in jobs:
        key=j['request_id'];req=json.loads((author/(key+'.request.json')).read_text());raw=json.loads((author/(key+'.raw.json')).read_text())
        position={'OFF':0,'R':2,'L':4}[j['condition']]+int(j['seed']==29)
        decision,note=DECISIONS[j['index']][position];status={'A':'accept','R':'reject','U':'uncertain'}[decision]
        assert raw['finish_reason']=='natural_stop'
        c=conditions[j['index'],j['condition']]
        reviews.append(dict(request_identity=key,raw_identity=digest(raw),messages_identity=digest(req['messages']),
            index=j['index'],condition=j['condition'],seed=j['seed'],split=j['split'],status=status,rationale=note,
            evidence_identity=evidence[j['index']-1]['evidence_identity'],visible_source_ids=c['source_ids'],
            review_scope='Full visible input and answer; source excerpts and relevant temporal contradictions inspected. Not an exhaustive claim that every private historical turn was read.',
            checks=dict(technical_completion=True,exact_input=True,semantic_source_time_task_admission=(status=='accept')),
            unresolved_claims=[note] if status=='uncertain' else [],
            historical_uptake=(j['index'],j['condition'],j['seed']) in historical))
        requests[key]=req;raws[key]=raw
    doc=dict(reviewer=contract['admission']['reviewer'],independent_human_truth=False,
        contract_sha256=sha256_file(OUT/'condition_contract_private.json'),author_runtime_sha256=sha256_file(author/'runtime.json'),
        decision_table_sha256=sha256_file(Path(__file__)),old_q_m_used=False,repairs=0,rows=reviews)
    with (OUT/'admission_reviews_private.json').open('x') as f:f.write(json.dumps(doc,ensure_ascii=False,indent=2)+'\n')
    accepted=[r for r in reviews if r['status']=='accept']
    counts=Counter(r['status'] for r in reviews)
    coverage=Counter((r['index'],r['condition']) for r in accepted)
    missing=[dict(index=i,condition=c) for i,c in conditions if not coverage[i,c]]
    try:
        admitted_rows(contract,jobs,requests,raws,{r['request_identity']:r for r in reviews})
        gate=dict(passed=True,error=None)
    except ValueError as exc:gate=dict(passed=False,error=str(exc))
    summary=dict(status='ADMISSION_GATE_PASSED' if gate['passed'] else 'ADMISSION_GATE_FAILED_NO_TRAINING',
        counts=dict(counts),by_split={s:dict(Counter(r['status'] for r in reviews if r['split']==s)) for s in ('train','dev')},
        by_condition={c:dict(Counter(r['status'] for r in reviews if r['condition']==c)) for c in ('OFF','R','L')},
        coverage=[dict(index=i,condition=c,accepted=coverage[i,c]) for i,c in conditions],
        missing_prefix_conditions=missing,historical_uptake_train_prefixes=sorted({r['index'] for r in accepted if r['split']=='train' and r['historical_uptake']}),
        gate=gate,training_updates=0,adapter_created=False,repairs=0,paid_api_usd=0,
        supervision_exported=False,decision='Do not relax the pre-generation coverage gate after seeing outcomes; preserve all decisions and investigate provenance.')
    with (OUT/'admission_summary.json').open('x') as f:f.write(json.dumps(summary,ensure_ascii=False,indent=2)+'\n')
    print(json.dumps({k:v for k,v in summary.items() if k!='coverage'},ensure_ascii=False))

if __name__=='__main__':main()
